"// Declare Variables
const info = arguments[0];
const rect = arguments[1];
const lineHeight = this.lineHeight();
const padding = this.itemPadding();
const c1 = ColorManager.dimColor1();
const c2 = ColorManager.dimColor2();

// Draw Actors
const minimumScale = true;
this.drawCenteredPicture(info.picture, rect.x, rect.y, rect.width, rect.height, minimumScale);
let ch = rect.height;
if (this.actorStyle() === 'sprite') {
    ch -= lineHeight - 8;
} else if (this.actorStyle() === 'svbattler') {
    ch -= lineHeight - 12;
}
this.drawActors(info, rect.x + padding, rect.y, rect.width - padding * 2, ch);

// Draw Gradients
this.contents.gradientFillRect(rect.x, rect.y, rect.width, lineHeight, c2, c1, true);
if (info.gold || info.description) {
    const gy = rect.y + rect.height - lineHeight;
    this.contents.gradientFillRect(rect.x, gy, rect.width, lineHeight, c1, c2, true);
}

// Draw Data
this.contents.fontSize = 18;
y = rect.y;
this.drawPlaytime(info, rect.x + padding, y, rect.width - padding * 2, 'right');
this.drawTimestamp(info, rect.x + padding, y, rect.width - padding * 2, 'center');
y = rect.y + rect.height - lineHeight;
if (info.gold) {
    this.drawCurrency(info, rect.x + padding, y, rect.width - padding * 2);
}

// Draw Description
y = rect.y + rect.height - lineHeight;
this.drawDescription(info, rect.x + padding, y, rect.width - padding * 2, 'left');"

