y -= lineHeight;
this.drawPlaytime(info, rect.x + padding, y, rect.width - padding * 2, 'center');
if (info.gold) {
    y -= lineHeight;
    this.drawCurrency(info, rect.x + padding, y, rect.width - padding * 2);
}"

